package com.google.gson.stream;

import java.io.*;
import java.io.Closeable;
import java.io.Flushable;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertSame;

public class JsonWriter_value_TriageGen1Test {

    private StringWriter out;
    private JsonWriter jsonWriter;

    @Before
    public void setUp() {
        out = new StringWriter();
        jsonWriter = new JsonWriter(out);
    }

    @Test
    public void testValue_NormalDouble() throws IOException {
        jsonWriter.beginObject();
        jsonWriter.name("testValue");
        JsonWriter result = jsonWriter.value(123.45);
        jsonWriter.endObject();

        assertEquals("{\"testValue\":123.45}", out.toString());
        assertSame(jsonWriter, result);
    }

    @Test
    public void testValue_Zero() throws IOException {
        jsonWriter.beginArray();
        jsonWriter.value(0.0);
        jsonWriter.endArray();

        assertEquals("[0.0]", out.toString());
    }

    @Test
    public void testValue_NegativeDouble() throws IOException {
        jsonWriter.beginArray();
        jsonWriter.value(-50.5);
        jsonWriter.endArray();

        assertEquals("[-50.5]", out.toString());
    }

    @Test(expected = IllegalArgumentException.class)
    public void testValue_NaN() throws IOException {
        jsonWriter.value(Double.NaN);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testValue_PositiveInfinity() throws IOException {
        jsonWriter.value(Double.POSITIVE_INFINITY);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testValue_NegativeInfinity() throws IOException {
        jsonWriter.value(Double.NEGATIVE_INFINITY);
    }

    @Test
    public void testValue_LargeDouble() throws IOException {
        double largeValue = 1.7976931348623157E308;
        jsonWriter.beginArray();
        jsonWriter.value(largeValue);
        jsonWriter.endArray();

        // Double.toString() for max double produces scientific notation
        assertEquals("[" + Double.toString(largeValue) + "]", out.toString());
    }
}
